const r="hw_suggestions";function o(){try{const t=localStorage.getItem(r);if(t)return JSON.parse(t)}catch{}return{subjects:[],classes:[],questions:[]}}function c(t){try{localStorage.setItem(r,JSON.stringify(t))}catch{}}function i(t,s){const e=s.trim();if(!e)return t;const n=t.filter(u=>u!==e);return n.unshift(e),n.slice(0,20)}function a(t){return o()[t]}function f(t,s){const e=o();e[t]=i(e[t],s),c(e)}function g(t){const s=o();for(const[e,n]of Object.entries(t))n&&(s[e]=i(s[e],n));c(s)}export{g as a,f as b,a as g};
